const points=Object.fromEntries(Object.entries(raw).map(([k,p])=>[k,[clamp(p[0]/w,0,1),clamp(p[1]/h,0,1)]]));let resultSrc=src;if(fg.backgroundRemoved){for(let i=0;i<mask.length;i++)if(!mask[i])r.data.data[i*4+3]=0;r.ctx.putImageData(r.data,0,0);resultSrc=r.canvas.toDataURL('image/png')}
