M.pngAngles=(o,t)=>{let a=Object.fromEntries(keys.map(k=>[k,0])),strength=clamp(o.characterDef?.motionStrength??.65,.1,1),side=o.view==='side',s=Math.sin(t*(o.pose==='run'?11:6));if(['walk','run','tiptoe'].includes(o.pose)){const stride=(o.pose==='run'?34:22)*strength;if(side)Object.assign(a,{la:s*stride*.7,ra:-s*stride*.7,ll:-s*stride,rl:s*stride,lk:Math.max(0,s)*stride*1.2,rk:Math.max(0,-s)*stride*1.2});else Object.assign(a,{la:s*5*strength,ra:-s*5*strength,le:-Math.max(0,s)*7*strength,re:Math.max(0,-s)*7*strength,ll:-Math.max(0,s)*5*strength,rl:Math.max(0,-s)*5*strength,lk:Math.max(0,s)*9*strength,rk:-Math.max(0,-s)*9*strength});}else if(!['idle','custom'].includes(o.pose)){const preset=M.poseAngles({...o,rig:{}},t);for(const k of keys)a[k]=(preset[k]||0)*strength}Object.assign(a,o.rig||{});return a};
